const NEIGHBOR_RESULT_METRICS = Object.freeze([
  { key: "water", label: "水源", unit: "" },
  { key: "grass", label: "草场", unit: "" },
  { key: "stability", label: "种群稳定", unit: "" },
  { key: "safety", label: "安全", unit: "" },
  { key: "reputation", label: "口碑", unit: "" },
  { key: "community", label: "社区支持", unit: "" }
]);
function neighborResultImpactChanges(beforeReserve = {}, afterReserve = {}) {
  const beforeEcology = beforeReserve.ecology || {};
  const afterEcology = afterReserve.ecology || {};
  const beforeCore = beforeReserve.coreResources || {};
  const afterCore = afterReserve.coreResources || {};
  return NEIGHBOR_RESULT_METRICS.map((metric) => {
    const before = metric.key === "water" || metric.key === "grass"
      ? Number(beforeEcology[metric.key]) || 0
      : metric.key === "community"
        ? Number(beforeCore.community) || 0
        : Number(beforeReserve[metric.key]) || 0;
    const after = metric.key === "water" || metric.key === "grass"
      ? Number(afterEcology[metric.key]) || 0
      : metric.key === "community"
        ? Number(afterCore.community) || 0
        : Number(afterReserve[metric.key]) || 0;
    const delta = Math.round(after - before);
    return { key: metric.key, label: metric.label, unit: metric.unit, before, after, delta };
  }).filter((item) => item.delta !== 0);
}
