function chapterCoreMetrics(reserve = {}, chapter = 1) {
  // The HUD species metric is a chapter roster metric. It must not be
  // recalculated from live populations, otherwise low water/grass or a
  // temporary migration makes an already-unlocked species disappear.
  const speciesCount = chapterSpeciesCount(reserve, chapter);
  const animals = repairChapterAnimalHud(reserve);
  const visitors = chapterVisitorTotal(reserve);
  const rareAnimal = rareAnimalChapterGate(reserve, chapter);
  const target = chapterTargets(chapter);
  const liveSpecies = speciesCount;
  const liveAnimals = Math.round(animals);
  const progression = reserve.progression || (reserve.progression = {});
  const storedBest = progression.coreBest || {};
  const sameChapter = Math.round(Number(storedBest.stage) || 0) === Math.round(chapter);
  const best = {
    stage: Math.round(chapter),
    species: Math.max(sameChapter ? Math.round(Number(storedBest.species) || 0) : 0, liveSpecies),
    animals: Math.max(sameChapter ? Math.round(Number(storedBest.animals) || 0) : 0, liveAnimals),
    visitors: Math.max(sameChapter ? Math.round(Number(storedBest.visitors) || 0) : 0, visitors)
  };
  progression.coreBest = best;
  const met = {
    species: best.species >= target.species,
    animals: best.animals >= target.animals,
    visitors: best.visitors >= target.visitors,
    rareAnimal: rareAnimal.met
  };
  const liveComplete = liveSpecies >= target.species && liveAnimals >= target.animals && visitors >= target.visitors;
  const percentage = (value, goal) => metricProgress(value, goal).percentage;
  return {
    species: liveSpecies,
    animals: liveAnimals,
    visitors,
    rareAnimal,
    rareAnimalState: normalizeRareAnimalState(reserve),
    best,
    met,
    liveComplete,
    target,
    percentages: {
      species: percentage(liveSpecies, target.species),
      animals: percentage(liveAnimals, target.animals),
      visitors: percentage(visitors, target.visitors)
    },
    complete: liveComplete
  };
}
function reserveProgressionFor(reserve = {}) {
  const prior = reserve.progression || {};
  const currentStage = Math.max(1, Math.min(CHAPTERS.length, Math.round(Number(prior.stage || prior.displayChapter) || 1)));
  let computed = computeReserveProgression(reserve || {});
  const coreBeforeAuction = chapterCoreMetrics(reserve, currentStage);
  const target = coreBeforeAuction.target || chapterTargets(currentStage);
  const rareState = normalizeRareAnimalState(reserve);
  const auction = rareState.auction || {};
  const otherCoreReady = coreBeforeAuction.species >= target.species
    && coreBeforeAuction.animals >= target.animals
    && coreBeforeAuction.visitors >= target.visitors;
  const auctionCanCloseSpeciesGap = coreBeforeAuction.species < target.species
    && coreBeforeAuction.species + 1 >= target.species;
  const auctionCanCloseAnimalGap = coreBeforeAuction.animals < target.animals
    && coreBeforeAuction.animals + 1 >= target.animals;
  const auctionRequired = !!(coreBeforeAuction.rareAnimal && coreBeforeAuction.rareAnimal.required);
  const auctionNeedsReconcile = auction.status === "submitted"
    || (auction.status === "settled" && auction.winner);
  if (auctionNeedsReconcile
      && coreBeforeAuction.visitors >= target.visitors
      && (auctionRequired || otherCoreReady || auctionCanCloseSpeciesGap || auctionCanCloseAnimalGap)) {
    settleRareAuctionForProgression(reserve, {
      playerName: "你"
    });
    computed = computeReserveProgression(reserve || {});
  }
  const keepStart = {
    chapterStart: prior.chapterStart || computed.chapterStart,
    stageStart: prior.stageStart || computed.stageStart
  };
  // Chapter promotion is deliberately one step at a time.  Older saves can
  // have a missing stage field; the simulator may then infer a stage from a
  // level value that is several chapters ahead.  Never let that inferred
  // value skip a chapter in the live progression state.
  const candidateStage = Math.max(
    currentStage,
    Math.min(currentStage + 1, Math.round(Number(computed.stage || currentStage)))
  );
  const core = chapterCoreMetrics(reserve, currentStage);
  if (currentStage >= CHAPTERS.length) {
    const finished = prior.chapterComplete === true
      || prior.stageComplete === true
      || core.complete === true
      || computed.chapterComplete === true
      || computed.stageComplete === true;
    return Object.assign({}, computed, keepStart, {
      stage: currentStage,
      displayChapter: currentStage,
      chapterComplete: finished,
      stageComplete: finished,
      coreBest: core.best,
      coreMetrics: finished ? Object.assign({}, core, { complete: true }) : core
    });
  }
  if (core.complete && currentStage < CHAPTERS.length) {
    const nextStage = currentStage + 1;
    const nextChapter = CHAPTERS[nextStage - 1] || CHAPTERS[currentStage - 1] || CHAPTERS[0];
    return Object.assign({}, computed, keepStart, {
      stage: nextStage,
      displayChapter: nextStage,
      nextTitle: nextChapter.title,
      coreBest: core.best,
      coreMetrics: core
    });
  }
  if (candidateStage <= currentStage) return Object.assign({}, computed, keepStart, { coreBest: core.best, coreMetrics: core });
  const currentChapter = CHAPTERS[currentStage - 1] || CHAPTERS[0];
  const nextChapter = CHAPTERS[currentStage] || currentChapter;
  return Object.assign({}, computed, keepStart, {
    stage: currentStage,
    displayChapter: currentStage,
    title: currentChapter.title,
    level: Math.max(1, Math.round(Number(prior.level) || currentChapter.level || 1)),
    storyLevel: Math.max(1, Math.round(Number(prior.level) || currentChapter.level || 1)),
    chapterComplete: false,
    stageComplete: false,
    levelUpgraded: false,
    nextTitle: nextChapter.title,
    coreBest: core.best,
    coreMetrics: core
  });
}
