function formatDisplayNumber(value, digits = 1) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return String(value == null ? "" : value);
  const places = Math.max(0, Math.min(1, Math.floor(Number(digits) || 0)));
  const scale = 10 ** places;
  const rounded = Math.sign(numeric) * Math.round((Math.abs(numeric) + Number.EPSILON) * scale) / scale;
  return String(Object.is(rounded, -0) ? 0 : rounded);
}
function normalizeDisplayNumericText(value, digits = 1) {
  const text = String(value == null ? "" : value);
  return text.replace(/\d+\.\d+/g, (raw) => formatDisplayNumber(raw, digits));
}
