function resolveRenderDpr(info = {}) {
  const nativeDpr = Math.max(1, Number(info.pixelRatio) || 1);
  const benchmark = Number(info.benchmarkLevel) || 0;
  // Use a 2x backing store on capable iPhones so text and UI edges stay crisp.
  // Keep the 1.5x fallback for low benchmark devices where a larger canvas can
  // exhaust the mini-game heap during long sessions.
  const cap = benchmark > 0 && benchmark <= 10 ? 1.5 : 2;
  return Math.min(nativeDpr, cap);
}
function resolveRuntimeInfo(runtime) {
  let system = {};
  if (runtime && typeof runtime.getSystemInfoSync === "function") {
    try { system = runtime.getSystemInfoSync() || {}; } catch (error) { system = {}; }
  }
  let device = {};
  if (runtime && typeof runtime.getDeviceInfo === "function") {
    try { device = runtime.getDeviceInfo() || {}; } catch (error) { device = {}; }
  }
  const pick = (key) => {
    const fromDevice = device && device[key];
    if (fromDevice !== undefined && fromDevice !== null && String(fromDevice) !== "") return fromDevice;
    return system[key];
  };
  return Object.assign({}, system, {
    platform: pick("platform"),
    system: pick("system"),
    brand: pick("brand"),
    model: pick("model")
  });
}
function canvasPlatformId(info = {}) {
  return String((info && (info.platform || info.system)) || "").toLowerCase();
}
function usesHarmonyPhysicalTouches(info = {}) {
  const platform = String((info && info.platform) || "").toLowerCase();
  const system = String((info && info.system) || "").toLowerCase();
  const brand = String((info && (info.brand || info.model)) || "").toLowerCase();
  return /ohos|harmony|openharmony/.test(platform)
    || /ohos|harmony|openharmony/.test(system)
    || ((/huawei|honor/.test(platform) || /huawei|honor/.test(brand)) && /harmony|ohos/.test(system + " " + platform));
}
function usesIosClient(info = {}) {
  const platform = String((info && info.platform) || "").toLowerCase();
  const system = String((info && info.system) || "").toLowerCase();
  return /ios|iphone|ipad/.test(`${platform} ${system}`);
}
function usesAndroidTouchCoordinates(info = {}) {
  const platform = String((info && info.platform) || "").toLowerCase();
  const system = String((info && info.system) || "").toLowerCase();
  return /android/.test(`${platform} ${system}`);
}
