  drawModalHeaderIcon(ctx, modal, cx, cy, size = 50) {
    if (modal && modal.player) {
      const overlayFriendName = modal.kind === "leaguePlayerDetail" && this.worldRowNeedsFriendNickname(modal.player, modal);
      // Friend profiles overlay the real WeChat nickname on the same shared
      // canvas. Drawing the avatar first would steal that surface and leave
      // the coded server name visible.
      if (!overlayFriendName && this.wechatFriends && typeof this.wechatFriends.drawWorldAvatar === "function") {
        const avatar = this.wechatFriends.drawWorldAvatar(ctx, cx - (size - 2) / 2, cy - (size - 2) / 2, size - 2, modal.player);
        if (avatar) {
          modal.renderedPlayerAvatar = Object.assign({ source: "wechat-open-data" }, avatar === true ? {} : avatar);
          return;
        }
      }
      modal.renderedPlayerAvatar = this.drawLeaguePlayerAvatar(ctx, modal.player, cx, cy, size - 2, true);
      return;
    }
    if (modal && modal.animal) {
      this.drawAnimalAvatar(ctx, modal.animal, cx, cy, size - 2, true);
      return;
    }
    if (modal && modal.collectionItem) {
      this.roundRect(ctx, cx - size / 2, cy - size / 2 + 3, size, size, 16, "rgba(18,61,52,.18)");
      this.roundRect(ctx, cx - size / 2, cy - size / 2, size, size, 16, "#fff7c7", "rgba(255,169,58,.52)");
      this.drawCollectionItemIcon(ctx, modal.collectionItem, cx, cy, size - 12);
      return;
    }
    if (modal && modal.wildernessItem) {
      const r = size / 2;
      this.roundRect(ctx, cx - r, cy - r, size, size, r, UI_THEME.ivory, "rgba(201,170,106,.54)");
      this.drawWildernessMaterialIcon(ctx, modal.wildernessItem, cx, cy, size - 5);
      return;
    }
    const icon = (modal && modal.icon) || "eye";
    const frame = this.uiIconFrame(icon);
    const image = frame && this.art && this.art.uiIcons && this.art.uiIcons[frame.key];
    if (image && image.loaded && ctx.drawImage) {
      const r = size / 2;
      this.roundRect(ctx, cx - r, cy - r, size, size, r, UI_THEME.ivory, "rgba(201,170,106,.54)");
      ctx.save();
      ctx.beginPath();
      ctx.arc(cx, cy, r - 3, 0, Math.PI * 2);
      ctx.clip();
      ctx.drawImage(image, 12, 12, 72, 72, cx - r + 2, cy - r + 2, size - 4, size - 4);
      ctx.restore();
      return;
    }
    this.roundRect(ctx, cx - size / 2, cy - size / 2 + 3, size, size, 16, "rgba(18,61,52,.18)");
    this.roundRect(ctx, cx - size / 2, cy - size / 2, size, size, 16, UI_THEME.ivory, "rgba(201,170,106,.48)");
    this.drawLargeIcon(ctx, icon, cx, cy, UI_THEME.forest700, size - 10);
  }
