    this.drawFittedTextBlock(ctx, promotion.title || "下一站 · 世界级自然地", infoX, promoY + 48, infoW, 23, { size: 15, minSize: 12, lineHeight: 21, weight: "700", color: "#173d34", maxChars: 28 });
    const barY = promoY + promoH - 29;
