  drawTourismProgressContent(ctx, modal, x, y, w, h) {
    const tourism = modal.tourism;
    const left = x + 28;
    const width = w - 56;
    const trendLabel = tourism.trend === "up" ? "↑ 上升中" : tourism.trend === "down" ? "↓ 经营走弱" : "→ 保持稳定";
    const trendColor = tourism.trend === "down" ? "#c94d3e" : tourism.trend === "up" ? "#168662" : "#68736b";
    this.text(ctx, tourism.maxLevel ? "已达最高星级" : `升至${tourism.stars + 1}星`, left, y + 25, 14, "#173d34", "700");
    this.text(ctx, `${trendLabel}  ${tourism.progress}%`, left + width, y + 25, 13, trendColor, "700", "right");
    this.roundRect(ctx, left, y + 36, width, 8, 4, "#d9dfc7");
    if (tourism.progress > 0) this.roundRect(ctx, left, y + 36, width * tourism.progress / 100, 8, 4, "#2f886a");
    this.text(ctx, `评分 ${tourism.score.toFixed(1)}${tourism.maxLevel ? " · 满星" : ` / ${tourism.nextScore}`}`, left, y + 65, 12, "#4b594e", "700");
    const rowH = Math.min(28, (h - 127) / Math.max(1, tourism.path.length));
    modal.renderedTourismPath = [];
    tourism.path.forEach((step, index) => {
      const top = y + 76 + index * rowH;
      if (step.current) this.roundRect(ctx, left - 4, top, width + 8, rowH - 1, 6, "#dfead1");
      const label = `${step.reached ? "★" : "☆"} ${step.stars}星 · ${step.title}`;
      this.text(ctx, label, left + 4, top + rowH * .72, 12, step.reached ? "#173d34" : "#68736b", step.current ? "700" : "400");
      this.text(ctx, step.current ? "当前" : `${step.score}分`, left + width - 4, top + rowH * .72, 11, "#95671d", "700", "right");
      modal.renderedTourismPath.push({ ...step, x: left, y: top, w: width, h: rowH });
    });
    const guidance = tourism.maxLevel
      ? "已达最高星级；继续保持活跃度、留存和生态平衡。"
      : `晋级：${tourism.nextScore}分。${(tourism.nextSteps || []).slice(1).join("；")}。`;
    const risk = (tourism.downgradeReasons || []).filter((item) => !/保持稳定/.test(item)).slice(0, 2).join("；");
    this.drawFittedTextBlock(ctx, `${guidance}${risk ? ` 降星原因：${risk}。` : ""} 评分按日缓慢追踪，避免一次操作跳级。`, left, y + h - 31, width, 32, { size: 11, minSize: 9, lineHeight: 13, color: "#4b594e" });
  }
