        risk: choice.risk || "safe",
        primaryBenefit: `游客约${businessPreview.after.visitors}人`,
        primaryCost: primary.cost,
        effectText: `${effectPreview({ effects: adjusted.effects })}${shortfallText}`,
        consequenceText: `下次贡献约${businessPreview.after.income}星币，未入账`,
        ecologyDetail: `${primary.benefit}；${primary.cost}`,
