      ctx.arc(x, y - 5, 4.2, 0, Math.PI * 2);
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(x - 8, y + 9);
      ctx.quadraticCurveTo(x - 6.5, y - 1, x, y - 1);
      ctx.quadraticCurveTo(x + 6.5, y - 1, x + 8, y + 9);
      ctx.closePath();
      ctx.fill();
