  drawFriendContractHistoryPanel(ctx, x, y, w, reserve = {}) {
    const history = friendContractHistory(reserve);
    const mailbox = this.cloudService && this.cloudService.friendContractMailbox || { sent: [], received: [] };
    const allies = this.friendAidAllies();
    const normalizedFriendId = (value) => String(value || "").replace(/^cloud_/, "").trim().toLowerCase();
    const partnerNameForEntry = (entry = {}) => {
      const entryId = normalizedFriendId(entry.partnerId);
      const local = allies.find((friend) => {
        const friendId = normalizedFriendId(friend && (friend.id || friend.openId || friend.worldPlayerId));
        return entryId && friendId && entryId === friendId;
      });
      return (local && local.name) || entry.partnerName || "好友";
    };
    const sent = history.filter((entry) => entry.type === "started" || entry.type === "player_completed").length
      + (mailbox.sent || []).length;
    const received = history.filter((entry) => entry.type === "partner_completed" || entry.type === "received_completed").length
      + (mailbox.received || []).length;
    const ended = history.filter((entry) => entry.type === "completed" || entry.type === "expired").length
      + (mailbox.sent || []).concat(mailbox.received || []).filter((entry) => ["completed", "expired"].includes(entry.status)).length;
    const recent = history
      .filter((entry) => ["completed", "expired", "partner_completed", "player_completed"].includes(entry.type))
      .slice(-2)
      .reverse()
      .concat((mailbox.sent || []).concat(mailbox.received || [])
        .filter((entry) => ["completed", "expired"].includes(entry.status)).slice(0, 2));
    const recentRewards = history
      .filter((entry) => entry.type === "completed" && entry.rewardText)
      .slice(-2)
      .reverse()
      .concat((mailbox.sent || []).concat(mailbox.received || [])
        .filter((entry) => entry.status === "completed")
        .map((entry) => {
          const objective = FRIEND_CONTRACTS.find((item) => item.id === entry.objectiveId);
          return objective ? { rewardText: friendContractRewardText(objective.reward) } : null;
        }).filter(Boolean).slice(0, 2));
    const h = 146;
    this.drawPremiumParchmentPanel(ctx, x, y, w, h, 14, { rivets: true, active: true });
    this.text(ctx, "好友合同历史", x + 16, y + 24, 15, "#1c3325", "700");
    this.text(ctx, "发起、收到、结束与奖励都会保留", x + 16, y + 43, 10, "#66715f", "600");
    const metrics = [
      { label: "发起", value: sent },
      { label: "收到", value: received },
      { label: "已结束", value: ended }
    ];
    const metricW = (w - 32) / metrics.length;
    metrics.forEach((metric, index) => {
      const mx = x + 16 + metricW * index;
      this.roundRect(ctx, mx, y + 52, metricW - 6, 24, 8, index === 2 ? "#e6f2dc" : "#f5f1e5", "rgba(47,125,98,.14)");
      this.text(ctx, `${metric.label} ${metric.value}`, mx + (metricW - 6) / 2, y + 68, 10, index === 2 ? "#1f7a52" : "#526359", "700", "center");
    });
    const latestText = recent.length
      ? recent.map((entry) => `${partnerNameForEntry(entry)} · ${entry.rewardText || (entry.type === "partner_completed" ? "好友已回应" : "已记录")}`).join("  |  ")
      : "暂无记录；先从好友列表选择好友并查看详情。";
    this.text(ctx, this.truncateTextToWidth(ctx, latestText, w - 34, 9, "600"), x + 17, y + 90, 9, "#6b745f", "600");
    const rewardText = recentRewards.length
      ? recentRewards.map((entry) => entry.rewardText).join("  |  ")
      : "完成合同后，基金、补给与收藏物资会记入这里。";
    this.text(ctx, this.truncateTextToWidth(ctx, `得到物资：${rewardText}`, w - 34, 9, "600"), x + 17, y + 104, 9, "#8b6f2a", "600");
    const buttonW = (w - 42) / 2;
    this.button(ctx, x + 14, y + 116, buttonW, 28, "查看合同历史", "#1c5f46", () => this.openFriendContractInboxModal(), "#fff8df", 10);
    this.button(ctx, x + 28 + buttonW, y + 116, buttonW, 28, "去好友列表", "#e8ddbd", () => this.navigateToFriendList(), "#26352b", 10);
    this.renderedFriendContractHistory = {
      x, y, w, h,
      counts: { sent, received, ended },
      latest: recent.map((entry) => entry.id || entry.type),
      shortcut: { label: "去好友列表" }
    };
    return h;
  }
