        ctx.fillStyle = "rgba(226,92,42,.82)";
        ctx.beginPath();
        ctx.moveTo(x, y - size);
        ctx.quadraticCurveTo(x + size, y, x, y + size * .65);
        ctx.quadraticCurveTo(x - size, y, x, y - size);
