        if (!locatedStoryRegion || !locatedStoryAction || marker.regionId !== locatedStoryRegion) return true;
        if (marker.presentation === "resource-flow" || marker.type === "crisis" || marker.type === "visitorIncident") return true;
        if (marker.eventType || marker.type === "animalInteraction" || marker.kind === "animalInteraction") return true;
