    const liveReserve = liveWorld.reserve || {};
    const liveAnimalTaskId = ((liveReserve.animalPatrolLead || {}).id) || "";
    states.forEach((state) => {
      (state.subMetrics || []).forEach((metric) => { metrics[metric.id] = metric; });
    });
    const activeEmergency = liveReserve.emergency && liveReserve.emergency.active;
    const todayOperations = (((liveReserve.development || {}).operations || {}).today) || {};
    const activeVisitorEvent = !!(activeEmergency && this.isVisitorSandboxReminder(activeEmergency));
    const visitorTroubleActive = hasVisitorTrouble(todayOperations);
    const activeNeighborType = activeEmergency && String(activeEmergency.type || "").startsWith("neighbor_")
      ? activeEmergency.type : "";
