      const id = String(marker.id || "");
      const eventType = String(marker.eventType || "");
      const title = String(marker.title || marker.label || "").trim().toLowerCase();
      const identity = `${id} ${title} ${String(marker.visualKind || "")}`.toLowerCase();
      const region = String(marker.regionId || "center");
      const action = String(marker.recommendAction || marker.type || "event");
      if (/reserve_network|相邻保护区|邻区|跨区/.test(identity) || eventType.startsWith("neighbor_")) return "neighbor";
      if (eventType === "animal_interaction" || marker.animalInteractionId || marker.type === "animalInteraction" || marker.kind === "animalInteraction") {
        return `animal:${marker.animalInteractionId || id || `${region}:${title}`}`;
      }
      if (eventType) return `event:${region}:${action}`;
