  openChapterProgressDetail(force = false) {
    const reserve = (this.state.world || {}).reserve || {};
    const progression = this.reserveProgression(reserve);
    const stage = Math.max(1, Math.round(Number(progression.stage || progression.level) || 1));
    this.state.ui = Object.assign({}, this.state.ui || {});
    if (!force && Number(this.state.ui.chapterProgressSeenLevel) === stage) {
      this.toast("本章晋级路径已经看过，可点击章节进度随时查看");
      return false;
    }
    this.state.ui.chapterProgressSeenLevel = stage;
    saveState(this.state);
    this.infoDetailModal = this.buildChapterProgressDetail();
    this.render();
    return true;
  }
  openCoreMetricDetail(metricId) {
    const details = this.buildChapterProgressDetail().metricDetails || {};
    const detail = details[metricId];
    if (!detail) return false;
    const kind = metricId === "species" ? "populationMetricDetail" : metricId === "animals" ? "animalMetricDetail" : "visitorMetricDetail";
    const items = Array.isArray(detail.items) ? detail.items.filter((item) => item.tag !== "分享任务" || (metricId !== "animals" && metricId !== "visitors")) : detail.items;
    this.infoDetailModal = Object.assign({}, detail, { kind, items });
    if (metricId === "animals" || metricId === "visitors") {
      const shareReward = shareRewardPreview(this.state, {
        rewardType: metricId,
        sourceKind: metricId === "animals" ? "animal" : "visitor"
      });
      if (shareReward.eligible) {
        const shareRow = shareRewardBoardRow(shareReward);
        const shareItem = {
          tag: "分享任务",
          title: shareRow.title,
          body: `截下第${shareReward.chapter || 1}章的${shareReward.speciesLabel || "本章种群"}。完成微信分享后增加 ${shareReward.amount}${shareReward.unit}。本章还可 ${shareReward.remaining}/${shareReward.limit} 次。`,
          noCompact: true,
          largeText: true,
          stackTag: true,
          inlineTitle: true,
          action: () => this.shareMetricReward(metricId)
        };
        const next = items.slice();
        const anchor = next.findIndex((item) => typeof item.action === "function");
        if (anchor >= 0) next.splice(anchor, 0, shareItem);
        else next.push(shareItem);
        this.infoDetailModal.items = next;
      }
    }
    this.render();
    return true;
  }
  shareMetricReward(metricId) {
    const rewardType = metricId === "animals" ? "animals" : "visitors";
    this.shareRewardReturnMetric = rewardType;
    const started = this.shareForestPostcard(null, {
      rewardType,
      sourceKind: rewardType === "animals" ? "animal" : "visitor"
    });
    if (started === false) this.openCoreMetricDetail(rewardType);
    return started;
  }
  claimAnimalTotalAd() {
    if (this.rewardedVideoWatchBlocked()) return false;
    const reserve = ((this.state.world || {}).reserve) || {};
    const status = animalTotalAdStatus(reserve);
    if (!status.eligible) {
      this.toast("本章幸运迁入已用完");
      this.openCoreMetricDetail("animals");
      return false;
    }
    const animalAd = this.rewardedAnimalAds || (this.rewardedAnimalAds = this.rewardedAdFor(REWARDED_ANIMAL_AD_CONFIG));
    if (!animalAd || (typeof animalAd.available === "function" && !animalAd.available())) {
      this.toast("暂时无法开启幸运迁入，请稍后再试");
      return false;
    }
    this.toast("正在开启幸运迁入…");
    this.bindRewardedAdResult(animalAd, (adResult) => {
      const adCompletion = {
        completed: !!(adResult && adResult.completed),
        reason: String((adResult && adResult.reason) || "")
      };
      if (!adCompletion.completed) {
        if (typeof console !== "undefined" && console.info) {
          console.info("[AnimalTotalAd] 未发放", {
            ...adCompletion,
            error: (adResult && adResult.error) || null
          });
        }
        this.toastRewardedAdFailure(adCompletion, "这次没有获得迁入动物");
        return;
      }
      const currentReserve = ((((this.state || {}).world || {}).reserve) || reserve);
      const reward = applyAnimalTotalAdReward(currentReserve);
      if (typeof console !== "undefined" && console.info) {
        console.info("[AnimalTotalAd] 完播结算", {
          ...adCompletion,
          ok: !!reward.ok,
          amount: Number(reward.amount) || 0,
          before: Number(reward.before) || 0,
          after: Number(reward.after) || 0,
          reason: String(reward.reason || "")
        });
      }
      if (!reward.ok) {
        this.toast(reward.reason === "chapter_cap" || reward.reason === "daily_cap" ? "本章幸运迁入已用完" : "当前没有可迁入的动物");
        this.openCoreMetricDetail("animals");
        return;
      }
      this.commitReserveProgression(currentReserve);
      saveState(this.state);
      this.playSfx("success");
      this.reserveDisplayTargetCache = null;
      this.reserveDisplayTargetRefreshLeft = 0;
      this.numberAnimationBurstUntil = Date.now() + 2200;
      this.numberAnimationBurstCause = "task";
      this.toast(`幸运获得迁入动物 +${reward.amount}`);
      this.openCoreMetricDetail("animals");
    });
    return true;
  }
