  reconcileFriendContractMailbox(mailbox = {}) {
    const reserve = ((this.state.world || {}).reserve) || {};
    const allies = this.friendAidAllies();
    const sent = Array.isArray(mailbox.sent) ? mailbox.sent : [];
    sent.filter((entry) => entry && entry.status === "completed").forEach((entry) => {
      const state = friendContractStatus(reserve, allies, Date.now());
      const slot = (state.slots || []).find((item) => this.friendContractRemoteId(item) === String(entry.contractId || "")
        || (entry.clientContractId && item.clientContractId === String(entry.clientContractId)));
      if (!slot || slot.status === "completed" || slot.status === "expired" || !slot.started) return;
      const result = completeFriendContractSide(reserve, allies, "partner", "好友执行合同", Date.now(), slot.id);
      if (result.ok) saveState(this.state);
    });
    return mailbox;
  }
  refreshFriendContractMailbox(force = true) {
    const cloud = this.cloudService;
    if (!cloud || typeof cloud.refreshFriendContractMailbox !== "function") return Promise.resolve(null);
    return Promise.resolve(cloud.refreshFriendContractMailbox(force)).then((mailbox) => {
      this.reconcileFriendContractMailbox(mailbox || {});
      this.render();
      return mailbox;
    });
  }
