    this.button(ctx, x + 12, buttonY + 42, w - 24, 32, "合同历史", "#f4edda", () => this.openFriendContractInboxModal(), "#1f6f54", 11);
    const subscriptionStatus = controller ? controller.subscriptionStatus : "unsupported";
    const subscriptionLabel = subscriptionStatus === "requesting" ? "正在开启…" : subscriptionStatus === "accepted" ? "关系链提醒已开启" : subscriptionStatus === "partial" ? "补充开启另一项提醒" : "开启互动与超越提醒";
    this.button(ctx, x + 12, buttonY + 84, w - 24, 32, subscriptionLabel, subscriptionStatus === "accepted" ? "#e6f2dc" : "#1f7a52", () => this.requestRelationshipNotifications(), subscriptionStatus === "accepted" ? "#1f7a52" : "#fff8df", 11);
