    const titleLines = Math.max(1, Math.min(2, this.wrapTextLines(ctx, title, titleW, titleSize, "700").length));
    const bodyLines = body ? Math.max(1, Math.min(item.tight ? 3 : item.noCompact ? 5 : 3, this.wrapTextLines(ctx, body, w - 28, item.largeText ? 13 : 12).length)) : 0;
    const bodyStart = inlineTag ? 50 + (titleLines - 1) * titleLineHeight : stackedTag ? 70 + (titleLines - 1) * titleLineHeight : 48 + (titleLines - 1) * titleLineHeight;
    if (inlineTag) return Math.max(item.tight ? 66 : 70, bodyStart + Math.max(body ? 1 : 0, Math.min(item.tight ? 3 : 2, bodyLines)) * 15 + (item.tight ? 4 : 8));
    if (stackedTag) return Math.max(78, bodyStart + Math.max(body ? 1 : 0, Math.min(2, bodyLines)) * 15 + 6);
